const binaryData = $binary.productImage;
const base64Image = binaryData.data;
const mimeType = binaryData.mimeType || 'image/jpeg';

return [{
  json: {
    imageBase64: base64Image,
    mimeType: mimeType,
    category: $json.body.category || 'general',
    imageUrl: $json.body.imageUrl
  },
  binary: $binary
}];

const content = $json.message?.content || '{}';
let parsedContent;

try {
  parsedContent = JSON.parse(content);
} catch (e) {
  return [{
    json: {
      valid: false,
      errors: ['Invalid JSON format'],
      content: content,
      originalData: $json
    }
  }];
}

const errors = [];

// Validate title length (max 60 chars)
if (!parsedContent.title || parsedContent.title.length > 60) {
  errors.push(`Title too long: ${parsedContent.title?.length || 0} chars (max 60)`);
}

// Validate meta description length (max 155 chars)
if (!parsedContent.metaDescription || parsedContent.metaDescription.length > 155) {
  errors.push(`Meta description too long: ${parsedContent.metaDescription?.length || 0} chars (max 155)`);
}

// Validate description exists and word count
if (!parsedContent.description) {
  errors.push('Description missing');
} else {
  const wordCount = parsedContent.description.split(/\s+/).length;
  if (wordCount < 100 || wordCount > 200) {
    errors.push(`Description word count: ${wordCount} (target: 150 words)`);
  }
}

// Validate bullet features (should have 5)
if (!parsedContent.bulletFeatures || parsedContent.bulletFeatures.length !== 5) {
  errors.push(`Bullet features count: ${parsedContent.bulletFeatures?.length || 0} (expected: 5)`);
}

// Validate tags (should have 10)
if (!parsedContent.tags || parsedContent.tags.length !== 10) {
  errors.push(`Tags count: ${parsedContent.tags?.length || 0} (expected: 10)`);
}

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    content: parsedContent,
    originalData: $json
  }
}];

