const prices = $input.all().flatMap(item => {
  const results = item.json.shopping_results || [];
  return results.map(r => parseFloat(r.price?.replace(/[^0-9.]/g, '') || 0)).filter(p => p > 0);
});

if (prices.length === 0) {
  return [{
    json: {
      suggestedPrice: null,
      priceRange: { min: 0, max: 0 },
      competitorCount: 0,
      pricingStrategy: 'No competitor data available'
    }
  }];
}

prices.sort((a, b) => a - b);
const min = prices[0];
const max = prices[prices.length - 1];
const median = prices[Math.floor(prices.length / 2)];
const avg = prices.reduce((sum, p) => sum + p, 0) / prices.length;

// Competitive pricing: slightly below median
const suggestedPrice = Math.round(median * 0.95 * 100) / 100;

return [{
  json: {
    suggestedPrice: suggestedPrice,
    priceRange: { min, max, median, average: Math.round(avg * 100) / 100 },
    competitorCount: prices.length,
    pricingStrategy: `Competitive pricing at ${Math.round((median - suggestedPrice) / median * 100)}% below median`,
    allData: $input.all()[0].json
  }
}];

