const reviews = $json.reviews || [];

if (reviews.length === 0) {
  return [{
    json: {
      sentiment: 'neutral',
      positiveThemes: [],
      negativeThemes: [],
      averageRating: 0,
      reviewCount: 0
    }
  }];
}

const positiveWords = ['great', 'excellent', 'amazing', 'love', 'perfect', 'best', 'quality', 'recommend', 'happy', 'satisfied'];
const negativeWords = ['bad', 'poor', 'terrible', 'worst', 'disappointed', 'broken', 'defective', 'waste', 'avoid', 'cheap'];

let positiveCount = 0;
let negativeCount = 0;
const positiveThemes = new Set();
const negativeThemes = new Set();

reviews.forEach(review => {
  const text = (review.text || '').toLowerCase();
  const rating = review.rating || 0;

  if (rating >= 4) positiveCount++;
  if (rating <= 2) negativeCount++;

  positiveWords.forEach(word => {
    if (text.includes(word)) positiveThemes.add(word);
  });

  negativeWords.forEach(word => {
    if (text.includes(word)) negativeThemes.add(word);
  });
});

const sentiment = positiveCount > negativeCount ? 'positive' : negativeCount > positiveCount ? 'negative' : 'neutral';
const avgRating = reviews.reduce((sum, r) => sum + (r.rating || 0), 0) / reviews.length;

return [{
  json: {
    sentiment: sentiment,
    positiveThemes: Array.from(positiveThemes).slice(0, 5),
    negativeThemes: Array.from(negativeThemes).slice(0, 5),
    averageRating: Math.round(avgRating * 10) / 10,
    reviewCount: reviews.length,
    positiveCount: positiveCount,
    negativeCount: negativeCount
  }
}];

const features = $json.message?.content || '{}';
let parsedFeatures;

try {
  parsedFeatures = JSON.parse(features);
} catch (e) {
  parsedFeatures = { productType: 'product', colors: [], materials: [], keyFeatures: [] };
}

const productType = parsedFeatures.productType || 'product';
const colors = (parsedFeatures.colors || []).join(', ');
const materials = (parsedFeatures.materials || []).join(', ');
const style = parsedFeatures.style || '';

const altText = `${productType}${colors ? ' in ' + colors : ''}${materials ? ' made of ' + materials : ''}${style ? ', ' + style + ' style' : ''}`;

return [{
  json: {
    altText: altText.substring(0, 125), // Keep under 125 chars for accessibility
    fullDescription: altText,
    productFeatures: parsedFeatures
  }
}];
